//! Types for the pure session-recording state machine.
//!
//! Mirrors `docs/design/06-session-recording.md` sections 4.6 and 5.2.
//! Nothing here performs I/O or reads a clock; time arrives inside events.
//! Session ids are generated by the caller (ULID strings) and passed in with
//! the event that starts a session.

use serde::{Deserialize, Serialize};

/// Session state machine states (design doc 4.6 / 5.1).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum State {
    /// Recording feature disabled or no session context.
    Idle,
    /// Enabled, waiting for a target game or a manual start.
    Armed,
    /// A part is open and being written.
    Recording,
    /// A split was requested; waiting for the keyframe boundary.
    Splitting,
    /// Finalizing the current part before the session ends or moves on.
    Stopping,
    /// The user stopped the session; game detection is suppressed.
    StoppedByUser,
}

/// Session mode from `session.mode`.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
pub enum Mode {
    /// Start automatically when a target game is detected.
    Auto,
    /// Start only on an explicit user request.
    #[default]
    Manual,
}

/// How a detected game process ended (from the detector).
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum ExitReason {
    /// Normal exit.
    Normal,
    /// The process crashed with an exit code.
    Crashed {
        /// Process exit code.
        code: u32,
    },
    /// Exit cause could not be determined; treated as a normal exit.
    Unknown,
}

/// Why a part was split.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum SplitReason {
    /// User pressed split.
    UserRequested,
    /// Part reached `max_part_minutes`.
    MaxDuration,
    /// Part reached `max_part_gb`.
    MaxSize,
    /// Encoder stream parameters changed.
    StreamParamsChanged,
    /// Layout configuration changed.
    ConfigChanged,
}

/// Why a part (and possibly its session) was finalized.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum EndReason {
    /// User pressed stop or disabled the feature.
    UserStop,
    /// Target game exited normally.
    GameExited,
    /// Target game crashed.
    GameCrashed,
    /// A different target game started while recording.
    GameSwitched,
    /// System suspend.
    Suspend,
    /// Part closed to start the next part.
    Split(SplitReason),
    /// Free disk space fell below the minimum.
    DiskLow,
    /// Disk full while writing.
    DiskFull,
    /// Output volume disappeared.
    VolumeGone,
    /// Other writer I/O error.
    WriterError,
    /// Service is shutting down.
    ServiceShutdown,
    /// Parts finalized by crash recovery at service start.
    ///
    /// The reducer never builds it. The daemon's startup salvage (issue #26) stores it in the
    /// library as `end_reason = 'recovered'` with `recovered = 1` on the salvaged part.
    Recovered,
}

/// Write failure reported by the worker.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum WriteError {
    /// No space left on the device.
    DiskFull,
    /// The output volume is gone.
    VolumeGone,
    /// Any other I/O error.
    Io,
}

impl WriteError {
    /// The `EndReason` used when this write error finalizes a part.
    pub fn end_reason(self) -> EndReason {
        match self {
            WriteError::DiskFull => EndReason::DiskFull,
            WriteError::VolumeGone => EndReason::VolumeGone,
            WriteError::Io => EndReason::WriterError,
        }
    }
}

/// Settings the reducer needs. Values of zero disable the matching limit.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct SessionConfig {
    /// Split a part after this many milliseconds (0 = off).
    pub max_part_ms: u64,
    /// Split a part after this many bytes (0 = off).
    pub max_part_bytes: u64,
    /// Minimum free disk space in bytes before recording stops.
    pub min_free_bytes: u64,
    /// Allow a crashed game's session to continue on relaunch.
    pub join_relaunch_after_crash: bool,
    /// Length of the relaunch join window in milliseconds.
    pub join_window_ms: i64,
}

/// A session that can be continued by a relaunch of the same game.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Resume {
    /// Session to join.
    pub session_id: String,
    /// Game that must relaunch.
    pub game: String,
    /// Join window expiry, in the same clock as event `now_ms`.
    pub deadline_ms: i64,
}

/// Full reducer state. Immutable input to `reduce`; a new value is returned.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SessionState {
    /// Current machine state.
    pub state: State,
    /// Whether the feature is enabled.
    pub enabled: bool,
    /// Current start mode.
    pub mode: Mode,
    /// Limits and join settings.
    pub config: SessionConfig,
    /// Active session id, if any.
    pub session_id: Option<String>,
    /// Index of the current part within the session (1-based).
    pub part_index: u32,
    /// Target game currently detected, tracked independently of state.
    pub current_game: Option<String>,
    /// Game that will start once finalize completes (switch or relaunch).
    pub pending_start: Option<String>,
    /// Join window for a relaunch, if open.
    pub resume: Option<Resume>,
    /// Split currently waiting for its keyframe boundary.
    pub split_pending: Option<SplitReason>,
    /// Reason of the most recent finalize.
    pub end_reason: Option<EndReason>,
    /// Set when the feature is being disabled; state goes to Idle after finalize.
    pub disable_pending: bool,
    /// Set when the service is shutting down; state goes to Idle after finalize.
    pub shutdown_pending: bool,
    /// Last reported free disk bytes, if any tick has arrived.
    pub free_bytes: Option<u64>,
    /// Last time seen in an event, in milliseconds.
    pub now_ms: i64,
}

impl SessionState {
    /// Fresh state: Idle, disabled, manual mode, no session.
    pub fn new(config: SessionConfig) -> Self {
        SessionState {
            state: State::Idle,
            enabled: false,
            mode: Mode::Manual,
            config,
            session_id: None,
            part_index: 0,
            current_game: None,
            pending_start: None,
            resume: None,
            split_pending: None,
            end_reason: None,
            disable_pending: false,
            shutdown_pending: false,
            free_bytes: None,
            now_ms: 0,
        }
    }
}

/// Inputs to the reducer. Time-bearing events carry their own timestamp.
///
/// Events that may start a new session carry `new_session_id`, a fresh ULID
/// generated by the caller. It is used only if that event actually starts a
/// session; a join after a crash keeps the previous session id instead.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum Event {
    /// Enable or disable the feature, and set the mode.
    SetEnabled {
        /// Whether the feature should be enabled.
        enabled: bool,
        /// Start mode to apply.
        mode: Mode,
        /// Id for a session this event starts (ignored otherwise).
        new_session_id: String,
    },
    /// Replace the configuration.
    Config(SessionConfig),
    /// A target game was detected.
    GameStarted {
        /// Game identifier.
        game: String,
        /// Event time.
        now_ms: i64,
        /// Id for a session this event starts (ignored otherwise).
        new_session_id: String,
    },
    /// A detected game ended.
    GameEnded {
        /// Game identifier.
        game: String,
        /// How it ended.
        reason: ExitReason,
        /// Event time.
        now_ms: i64,
    },
    /// User pressed start.
    UserStart {
        /// Id for the session this start creates (ignored on a join).
        new_session_id: String,
    },
    /// User pressed stop.
    UserStop,
    /// User pressed split.
    UserSplit,
    /// Service is shutting down.
    Shutdown,
    /// Periodic tick with current part stats and free disk space.
    Tick {
        /// Tick time.
        now_ms: i64,
        /// Milliseconds the current part has been open.
        part_elapsed_ms: u64,
        /// Bytes written to the current part.
        part_bytes: u64,
        /// Free bytes on the output volume.
        free_bytes: u64,
    },
    /// System suspend.
    Suspend {
        /// Event time.
        now_ms: i64,
    },
    /// The encoder produced a keyframe at the split boundary.
    KeyframeArrived,
    /// No keyframe arrived within the expected window.
    KeyframeTimeout {
        /// Number of attempts made so far.
        attempts: u32,
    },
    /// Encoder stream parameters changed.
    StreamParamsChanged,
    /// Layout configuration changed.
    LayoutChanged,
    /// The worker reported a write failure.
    WriteFailed(WriteError),
    /// Finalize of the current part completed.
    FinalizeDone {
        /// Whether the part closed cleanly.
        ok: bool,
        /// Id for a session this completion starts (ignored otherwise).
        new_session_id: String,
    },
}

impl Event {
    /// Timestamp carried by this event, if any.
    pub fn now_ms(&self) -> Option<i64> {
        match self {
            Event::GameStarted { now_ms, .. }
            | Event::GameEnded { now_ms, .. }
            | Event::Suspend { now_ms }
            | Event::Tick { now_ms, .. } => Some(*now_ms),
            _ => None,
        }
    }
}

/// User-facing notices.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum Notice {
    /// Recording could not start because free space is below the minimum.
    DiskLowBlocked,
    /// Recording stopped because free space fell below the minimum.
    DiskLow,
    /// Recording stopped because of a write failure.
    WriteFailed(WriteError),
    /// A split was cancelled after repeated keyframe timeouts.
    KeyframeTimeout,
    /// A part closed with an error; the partial file was kept.
    PartialKept,
}

/// Error for a rejected command.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum CommandError {
    /// Start requested with no target game detected.
    NoTargetGame,
    /// Split requested while a split is already pending.
    AlreadyPending,
    /// Command rejected while finalizing.
    Busy,
    /// Start requested while the feature is disabled (Idle).
    NotEnabled,
    /// Stop or split requested while no recording is running.
    NotRecording,
    /// Start requested while a recording is already running.
    AlreadyRecording,
}

/// Effects returned by the reducer. The shell executes them in order.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum Effect {
    /// Start the encoder for a new session, or a joined relaunch.
    StartEncoder {
        /// Session the part belongs to.
        session_id: String,
        /// Part index.
        part_index: u32,
        /// Game identifier.
        game: String,
    },
    /// Open a new part file with this index.
    OpenPart {
        /// Index of the part to open.
        index: u32,
    },
    /// Close and finalize the current part.
    FinalizePart {
        /// Why the part is closing.
        reason: EndReason,
    },
    /// Stop the encoder; the session has no part open.
    StopEncoder,
    /// Ask the encoder for a keyframe.
    RequestKeyframe,
    /// Abandon a pending split.
    CancelSplit,
    /// Report the new state to subscribers.
    EmitStatus(State),
    /// Show a notice.
    Notify(Notice),
    /// Reply to a user command: Ok, or the reason it was rejected.
    Reply(Result<(), CommandError>),
}
